sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (!isLoading) {
        var currentUrl = top.location.href;
        var regex = /-1_uid_\d+/;
        var match = currentUrl.match(regex);
        var currentUrl_id = match ? match[0] : '-1_uid_46';
        var url = 'x/hsb11/mss-operation-request-workspace/record/x_hsb11_mss_oper_0_operation_request_case/' + currentUrl_id + '/params/query/';
        var encoded = encodeURIComponent("ssi_validation_method=" + newValue + '^form_type=1');
        url = url + encoded;
        top.window.location = url;
    }

    //Type appropriate comment here, and begin script below

}
